await page.locator("a.next").click();
await page.evaluate(() => ({url: location.href, title: document.title, answer: document.querySelector("h1")?.textContent}));

await page.goto("https://example.com/catalog");
await page.locator("a.next").first().click();
await page.evaluate(() => ({url: location.href, title: document.title, answer: document.querySelector("h1")?.textContent}));

await page.goto("https://example.com/catalog");
await page.locator("a.next").nth(0).click();
await page.evaluate(() => ({url: location.href, title: document.title, answer: document.querySelector("h1")?.textContent}));

await page.goto("https://example.com/catalog");
await page.click("a.next");
await page.evaluate(() => ({url: location.href, title: document.title, answer: document.querySelector("h1")?.textContent}));

await page.goto("https://example.com/catalog");
await page.fill("input[name=q]", "garden tools");
await page.evaluate(() => ({url: location.href, title: document.title, answer: document.querySelector("h1")?.textContent}));

await page.goto("https://example.com/catalog");
await page.press("input[name=q]", "Enter");
await page.evaluate(() => ({url: location.href, title: document.title, answer: document.querySelector("h1")?.textContent}));

await page.goto("https://example.com/catalog");
await page.getByRole("link", {name: "Next"}).first().click();
await page.evaluate(() => ({url: location.href, title: document.title, answer: document.querySelector("h1")?.textContent}));

await page.goto("https://example.com/catalog");
await page.getByLabel("Search").fill("garden tools");
await page.keyboard.press("Enter");
await page.evaluate(() => ({url: location.href, title: document.title, answer: document.querySelector("h1")?.textContent}));

await page.goto("https://example.com/catalog");
await page.goBack();
await page.evaluate(() => ({url: location.href, title: document.title, answer: document.querySelector("h1")?.textContent}));

await page.goto("https://example.com/catalog");
const title = await page.title();
return {answer: title};

