await page.goto("https://example.com/catalog");
await page.getByPlaceholder("Email").fill("reader@example.com");
await page.getByRole("button", {name: "Subscribe"}).click();
await page.evaluate(() => ({url: location.href, title: document.title, answer: document.querySelector("h1")?.textContent}));

await page.goto("https://example.com/catalog");
await page.getByText("Next page").click();
await page.evaluate(() => ({url: location.href, title: document.title, answer: document.querySelector("h1")?.textContent}));

await page.goto("https://example.com/catalog");
await page.getByRole("combobox", {name: "Country"}).selectOption("CA");
await page.evaluate(() => ({url: location.href, title: document.title, answer: document.querySelector("h1")?.textContent}));
